/* ===== data8d: topical questions, Topics 7 and 8 (acids/bases/salts/oxides; Periodic Table). Question text transcribed from the teacher's topical question sets; answers and mark allocations written for the hub, not the official mark scheme. ===== */
const X4_S=(f,n)=>"Cambridge IGCSE 0620 topical question, "+f+", Question "+n;
const X4_A=(n,t,m,q,ms)=>P(t,m,q,ms,X4_S("Properties of acids and bases",n));
const X4_Q1T=TBL(["","dilute ethanoic acid","dilute hydrochloric acid"],[["extent of dissociation","&nbsp;","&nbsp;"],["colour after adding universal indicator solution","&nbsp;","&nbsp;"],["observation when magnesium ribbon is added","&nbsp;","&nbsp;"]],480);
U[6].pp.push(
X4_A(1,"Weak and strong acid compared",6,"<p>Ethanoic acid is a weak acid and hydrochloric acid is a strong acid.</p><p>Complete the table to show the similarities and differences in the properties of samples of these two acids of equal concentration. [6]</p>"+X4_Q1T,["Extent of dissociation: ethanoic acid is partially (incompletely) dissociated (1); hydrochloric acid is completely dissociated (1).","Universal indicator: ethanoic acid gives orange / yellow (1); hydrochloric acid gives red (1).","Magnesium ribbon: ethanoic acid gives slow effervescence / few bubbles (1); hydrochloric acid gives rapid effervescence / many bubbles (1)."]),
X4_A(2,"Acid that forms a nitrate salt",1,"<p>Soluble salts can be made by adding a metal carbonate to a dilute acid.</p><p>Give the formula of the dilute acid which reacts with a metal carbonate to form a nitrate salt. [1]</p>",["HNO~3~ (1): nitric acid."]),
X4_A(3,"Magnesium carbonate and nitric acid",2,"<p>Dolomite is a similar rock to limestone. Dolomite contains magnesium carbonate, MgCO<sub>3</sub>.</p><p>Write a chemical equation for the reaction between magnesium carbonate and dilute nitric acid. [2]</p>",["MgCO~3~ + 2HNO~3~ → Mg(NO~3~)~2~ + H~2~O + CO~2~. Correct formulae (1); balanced (1)."]),
X4_A(4,"Hydrogen fuel cell half-equation",2,"<p>Hydrogen and oxygen react together in a hydrogen fuel cell.</p><p>(a) In a hydrogen fuel cell, the hydrogen molecules are converted into hydrogen ions, H<sup>+</sup>, according to the ionic half-equation shown.</p><p style='text-align:center'>H<sub>2</sub> → 2H<sup>+</sup> + 2e<sup>–</sup></p><p>What type of reaction does this ionic half-equation represent? [1]</p><p>(b) What <b>type</b> of substance reacts by donating hydrogen ions, H<sup>+</sup>? [1]</p>",["(a) Oxidation (1): hydrogen loses electrons.","(b) An acid (1): a proton donor."]),
X4_A(5,"Meaning of base (ammonia)",1,"<p>Ammonia is a weak base.</p><p>Explain the meaning of the term <i>base</i>. [1]</p>",["A base is a proton acceptor: it accepts H^+^ ions (1)."]),
X4_A(6,"Methyl orange in a strong acid",1,"<p>Chloric(V) acid, HC<i>l</i>O<sub>3</sub>, is a strong acid. It can be made from calcium chlorate(V).</p><p>What colour is methyl orange indicator in chloric(V) acid? [1]</p>",["Red (1): methyl orange is red in acid solutions."]),
X4_A(7,"Neutralising acidic soil",1,"<p>The following are the symbols and formulae of some elements and compounds.</p><p style='text-align:center'>Ar &nbsp; Ca(OH)<sub>2</sub> &nbsp; C<i>l</i><sub>2</sub> &nbsp; CO<sub>2</sub> &nbsp; Cu &nbsp; Fe &nbsp; SO<sub>2</sub> &nbsp; V<sub>2</sub>O<sub>5</sub></p><p>State which element or compound in the list is used to neutralise excess acidity in soil. [1]</p>",["Ca(OH)~2~ (1): calcium hydroxide (slaked lime) is a base."]),
X4_A(8,"Hydrochloric acid and magnesium",4,"<p>Acids have characteristic properties.</p><p>Hydrochloric acid reacts with magnesium.</p><p>Name the products of this reaction and give the observations. [4]</p>",["Products: magnesium chloride (1) and hydrogen (1).","Observations: bubbles / effervescence (1); the magnesium dissolves / gets smaller (1)."]),
X4_A(9,"Meaning of weak acid",1,"<p>Ethanoic acid, CH<sub>3</sub>COOH, is a weak acid. It reacts with copper(II) carbonate to form the salt copper(II) ethanoate, Cu(CH<sub>3</sub>COO)<sub>2</sub>.</p><p>What is meant by the term <i>weak</i> when applied to acids? [1]</p>",["A weak acid is only partially (incompletely) dissociated into ions in aqueous solution (1)."]),
X4_A(10,"Acid salt solution X",4,"<p>Potassium hydrogensulfate, KHSO<sub>4</sub>, is an acid salt. It dissolves in water to produce an aqueous solution, <b>X</b>, containing K<sup>+</sup>, H<sup>+</sup> and SO<sub>4</sub><sup>2–</sup> ions.</p><p>Describe what you would see when the following experiments are done.</p><ol type='a'><li>Magnesium ribbon is added to an excess of solution <b>X</b>. [2]</li><li>A flame test is done on solution <b>X</b>. [1]</li><li>An aqueous solution containing barium ions is added to solution <b>X</b>. [1]</li></ol>",["(a) Bubbles / effervescence (1); the magnesium dissolves (1).","(b) Lilac (pale purple) flame (1): potassium ions.","(c) White precipitate (1): barium sulfate."]),
X4_A(11,"Ammonia as a weak base",5,"<p>Ammonia reacts with water to form ions.</p><p style='text-align:center'>NH<sub>3</sub> + H<sub>2</sub>O ⇌ NH<sub>4</sub><sup>+</sup> + OH<sup>–</sup></p><ol type='a'><li>How does this equation show that ammonia, NH<sub>3</sub>, behaves as a base? [1]</li><li>Aqueous ammonia is described as a weak base.<br>Suggest the pH of aqueous ammonia. [1]</li><li>Describe what is seen when aqueous ammonia is added to aqueous copper(II) sulfate, until no further change is seen. [3]</li></ol>",["(a) NH~3~ accepts an H^+^ ion (proton) from water to form NH~4~^+^ (1).","(b) Any value from 8 to 11 (1).","(c) A pale blue precipitate forms (1); it dissolves in excess ammonia (1); to give a deep (dark) blue solution (1)."]),
X4_A(12,"Making hydrated iron(II) sulfate crystals",7,"<p>A student wanted to make hydrated iron(II) sulfate crystals, FeSO<sub>4</sub>•xH<sub>2</sub>O, by adding excess iron(II) carbonate to dilute sulfuric acid. The student followed the procedure shown.</p><p><b>step 1</b> Add dilute sulfuric acid to a beaker.<br><b>step 2</b> Add small amounts of iron(II) carbonate to the dilute sulfuric acid in the beaker until the iron(II) carbonate is in excess.<br><b>step 3</b> Filter the mixture formed in <b>step 2</b>.<br><b>step 4</b> Heat the filtrate until it is a saturated solution. Allow to cool.<br><b>step 5</b> Once cold, pour away the remaining solution. Dry the crystals between filter papers.</p><ol type='a'><li>Why must the iron(II) carbonate be added in excess in <b>step 2</b>? [1]</li><li>State <b>two</b> observations in <b>step 2</b> that would show that iron(II) carbonate was in excess.<br>1<br>2 [2]</li><li>Describe what should be done during <b>step 3</b> to ensure there is a maximum yield of crystals. [1]</li><li>A saturated solution is formed in <b>step 4</b>.<br>Describe what a saturated solution is. [2]</li><li>Name a different compound that could be used instead of iron(II) carbonate to produce hydrated iron(II) sulfate crystals from dilute sulfuric acid. [1]</li></ol>",["(a) So that all the sulfuric acid reacts (is used up / neutralised) (1).","(b) Effervescence stops (1); some solid iron(II) carbonate remains undissolved at the bottom of the beaker (1).","(c) Wash the residue with distilled water and add the washings to the filtrate (1).","(d) A solution containing the maximum amount of dissolved solute (1) at a particular temperature, so no more solute can dissolve (1).","(e) Iron(II) oxide (or iron(II) hydroxide, or iron) (1)."]),
X4_A(13,"Sodium hydrogen sulfate solution",3,"<p>Aqueous sodium hydrogen sulfate, NaHSO<sub>4</sub>(aq), contains the ions Na<sup>+</sup>(aq), H<sup>+</sup>(aq) and SO<sub>4</sub><sup>2–</sup>(aq).</p><p>Describe what you would see if the following experiments were done.</p><ol type='a'><li>A flame test was done on aqueous sodium hydrogen sulfate. [1]</li><li>Solid copper(II) oxide was added to aqueous sodium hydrogen sulfate and the mixture was warmed. [2]</li></ol>",["(a) Yellow flame (1): sodium ions.","(b) The black solid dissolves (disappears) (1); a blue solution forms (1)."]),
X4_A(14,"Why silver nitrate is acidified",1,"<p>Aqueous silver nitrate produces a yellow precipitate with both iodide ions and carbonate ions. When testing an unknown solution for iodide ions, the aqueous silver nitrate is acidified.</p><p>Explain why the aqueous silver nitrate is acidified. [1]</p>",["The acid reacts with (removes) any carbonate ions, so they cannot form a precipitate and give a false positive (1)."]),
X4_A(15,"Electrolysis of concentrated sodium chloride",8,"<p>A student used apparatus to electrolyse concentrated aqueous sodium chloride using inert electrodes. The apparatus has two gas-collecting tubes, each with an inert electrode at the bottom, joined by a central reservoir of concentrated aqueous sodium chloride and connected to a power supply.</p><ol type='a'><li>Suggest the name of a metal which could be used as the inert electrodes. [1]</li><li>Name the gas formed at the positive electrode. [1]</li><li>Write an ionic half-equation for the reaction occurring at the negative electrode. Include state symbols. [3]</li><li>How, if at all, does the pH of the solution change during the electrolysis? Explain your answer. [3]</li></ol>",["(a) Platinum (1) (graphite is not a metal).","(b) Chlorine (1).","(c) 2H^+^(aq) + 2e^−^ → H~2~(g). Reactant H^+^(aq) (1); electrons and correct balance (1); product H~2~(g) (1).","(d) The pH increases (1); H^+^ ions are discharged as hydrogen gas (1); this leaves an excess of OH^−^ ions, so the solution becomes alkaline (sodium hydroxide forms) (1)."]),
X4_A(16,"Ammonia and sulfuric acid",4,"<p>Ammonia is a base and reacts with sulfuric acid to form the salt, ammonium sulfate.</p><ol type='a'><li>What is meant by the term <i>base</i>? [1]</li><li>Name the industrial process used to manufacture sulfuric acid. [1]</li><li>Write a chemical equation for the reaction between ammonia and sulfuric acid. [2]</li></ol>",["(a) A proton (H^+^) acceptor (1).","(b) The Contact process (1).","(c) 2NH~3~ + H~2~SO~4~ → (NH~4~)~2~SO~4~. Correct formulae (1); balanced (1)."]),
X4_A(17,"Meaning of strong acid",2,"<p>Sulfuric acid is a strong acid.</p><p>What is meant by the term <i>strong acid</i>? [2]</p>",["A strong acid is one that is completely dissociated (ionised) in aqueous solution (1) to produce H^+^ ions (1)."]),
X4_A(18,"Dissociation of ethanoic acid",3,"<p>Ethanoic acid is a weak acid and hydrochloric acid is a strong acid. Both ethanoic acid and hydrochloric acid dissociate in aqueous solution.</p><ol type='a'><li>Define the term <i>acid</i>. [1]</li><li>The chemical equation shows the changes which occur when the strong acid, hydrochloric acid, is added to water.<br><span style='display:block;text-align:center'>HC<i>l</i>(aq) → H<sup>+</sup>(aq) + C<i>l</i><sup>–</sup>(aq)</span>Complete the chemical equation to show the changes which occur when the weak acid, ethanoic acid, is added to water.<br>CH<sub>3</sub>COOH(aq) ........ [2]</li></ol>",["(a) A proton (H^+^) donor (1).","(b) CH~3~COOH(aq) ⇌ H^+^(aq) + CH~3~COO^−^(aq). Correct products (1); reversible arrow ⇌ shows partial dissociation (1)."]),
X4_A(19,"Ammonia as a base",3,"<p>Phosphine, PH<sub>3</sub>, has a similar chemical structure to ammonia, NH<sub>3</sub>. Ammonia acts as a base when it reacts with sulfuric acid.</p><ol type='a'><li>What is meant by the term <i>base</i>? [1]</li><li>Write a chemical equation for the reaction between ammonia and sulfuric acid. [2]</li></ol>",["(a) A proton (H^+^) acceptor (1).","(b) 2NH~3~ + H~2~SO~4~ → (NH~4~)~2~SO~4~. Correct formulae (1); balanced (1)."]),
X4_A(20,"Ethanoic acid: acid and weak",2,"<p>Ethanoic acid, CH<sub>3</sub>COOH, is a weak acid.</p><ol type='a'><li>What is meant by the term <i>acid</i>? [1]</li><li>Why is ethanoic acid described as <i>weak</i>? [1]</li></ol>",["(a) A proton (H^+^) donor (1).","(b) It is only partially dissociated (ionised) in water (1)."]),
X4_A(21,"Showing ethanoic acid is an acid",3,"<p>How would you show that an aqueous solution of ethanoic acid, CH<sub>3</sub>COOH, is an acid <b>without</b> using an indicator or measuring the pH?</p><p>State the reagent you would use and give the expected observations. Write a chemical equation for the reaction that you describe.</p><p>reagent ........<br>expected observations ........<br>chemical equation ........ [3]</p>",["Reagent: magnesium (or a carbonate such as sodium carbonate) (1).","Observations: bubbles / effervescence and the metal dissolves (with a carbonate: effervescence of carbon dioxide) (1).","Equation, e.g. 2CH~3~COOH + Mg → (CH~3~COO)~2~Mg + H~2~ (1)."]),
X4_A(22,"Ammonia as a base: word equation",3,"<p>Ammonia is an important chemical. Ammonia is a base.</p><ol type='a'><li>In chemistry, what is meant by the term <i>base</i>? [1]</li><li>Write a word equation to show ammonia behaving as a base. [2]</li></ol>",["(a) A proton (H^+^) acceptor (1).","(b) ammonia + water ⇌ ammonium ions + hydroxide ions (or ammonia + acid → ammonium salt). Correct reactants (1); correct products (1)."]),
X4_A(23,"Distinguishing strong and weak acids",2,"<p>Measuring pH is one way of distinguishing between a strong acid and a weak acid. Describe another method.</p><p>method ........<br>results ........ [2]</p>",["Method: add the same piece of magnesium (or a carbonate) to equal volumes of equal-concentration acids (or compare the conductivity of the two solutions) (1).","Results: the strong acid reacts faster with more vigorous bubbling (or conducts better) than the weak acid (1)."]),
X4_A(24,"Chloric(V) acid as an acid",2,"<p>Chloric(V) acid, HC<i>l</i>O<sub>3</sub>, is a strong acid. It can be made from calcium chlorate(V).</p><ol type='a'><li>Define the term <i>acid</i> in terms of proton transfer. [1]</li><li>Complete the chemical equation to show HC<i>l</i>O<sub>3</sub> behaving as an acid in water.<br>HC<i>l</i>O<sub>3</sub> + H<sub>2</sub>O → ........ + ........ [1]</li></ol>",["(a) An acid is a proton (H^+^) donor (1).","(b) HClO~3~ + H~2~O → H~3~O^+^ + ClO~3~^−^ (1). Accept H^+^ in place of H~3~O^+^ if water is omitted."]),
X4_A(25,"Sulfuric acid equations",6,"<p>Dilute sulfuric acid reacts with bases, metals and carbonates.</p><p>Write chemical equations for the reaction of dilute sulfuric acid with each of the following:</p><ol type='a'><li>magnesium hydroxide [2]</li><li>zinc [2]</li><li>sodium carbonate. [2]</li></ol>",["(a) Mg(OH)~2~ + H~2~SO~4~ → MgSO~4~ + 2H~2~O. Correct formulae (1); balanced (1).","(b) Zn + H~2~SO~4~ → ZnSO~4~ + H~2~. Correct formulae (1); balanced (1).","(c) Na~2~CO~3~ + H~2~SO~4~ → Na~2~SO~4~ + H~2~O + CO~2~. Correct formulae (1); balanced (1)."]),
X4_A(26,"Calcium and cold water",4,"<p>The Group II element, calcium, reacts with cold water to form two products:</p><ul><li>a colourless gas, <b>P</b>, which ‘pops’ with a lighted splint</li><li>a weakly alkaline solution, <b>Q</b>, which turns milky when carbon dioxide is bubbled through it.</li></ul><ol type='a'><li>Name gas <b>P</b>. [1]</li><li>Identify the ion responsible for making solution <b>Q</b> alkaline. [1]</li><li>Suggest the pH of solution <b>Q</b>. [1]</li><li>Write a chemical equation for the reaction of calcium with cold water. [1]</li></ol>",["(a) Hydrogen (1).","(b) Hydroxide ion, OH^−^ (1).","(c) Any pH from 8 to 11 (1): a weakly alkaline solution.","(d) Ca + 2H~2~O → Ca(OH)~2~ + H~2~ (1)."]),
X4_A(27,"Ammonia solution",2,"<p>Ammonia is a base which forms a weakly alkaline solution when dissolved in water.</p><ol type='a'><li>Define the term <i>base</i>. [1]</li><li>Suggest the pH of aqueous ammonia. [1]</li></ol>",["(a) A proton (H^+^) acceptor (1).","(b) Any pH from 8 to 11 (1)."]),
X4_A(28,"Identifying substances from a list",5,"<p>This question is about solids, liquids and gases.</p><p>The list gives the names of nine substances.</p><p style='text-align:center'><b>aqueous copper(II) sulfate &nbsp;·&nbsp; aqueous potassium manganate(VII) &nbsp;·&nbsp; aqueous sodium chloride &nbsp;·&nbsp; dilute hydrochloric acid &nbsp;·&nbsp; ethanol &nbsp;·&nbsp; hexene &nbsp;·&nbsp; mercury &nbsp;·&nbsp; octane &nbsp;·&nbsp; water</b></p><p>Answer the following questions about these substances. Each substance may be used once, more than once or not at all.</p><p>State which substance:</p><ol type='a'><li>is an alkane [1]</li><li>is used, when acidified, to test for sulfur dioxide [1]</li><li>turns blue litmus red [1]</li><li>reacts with sodium to produce only aqueous sodium hydroxide and hydrogen [1]</li><li>is produced by the addition of steam to ethene. [1]</li></ol>",["(a) Octane (1).","(b) Aqueous potassium manganate(VII) (1): it turns from purple to colourless.","(c) Dilute hydrochloric acid (1).","(d) Water (1).","(e) Ethanol (1)."]),
X4_A(29,"Meaning of weak acid (two marks)",2,"<p>Some acids are described as weak acids.</p><p>State the meaning of the term <i>weak acid</i>. [2]</p>",["A weak acid is partially (incompletely) dissociated in aqueous solution (1); an equilibrium is set up, so few H^+^ ions are produced (1)."]),
X4_A(30,"Strong acids and sulfuric acid",4,"<p>Acids are important laboratory chemicals. Some acids completely dissociate in water to form ions.</p><ol type='a'><li>State the term applied to acids that completely dissociate in water. [1]</li><li>Complete the equation to show the complete dissociation of sulfuric acid in water.<br>H<sub>2</sub>SO<sub>4</sub> → ........ [2]</li><li>State the colour of methyl orange in sulfuric acid. [1]</li></ol>",["(a) Strong acids (1).","(b) H~2~SO~4~ → 2H^+^ + SO~4~^2−^. Correct ions (1); balanced charges / 2H^+^ (1).","(c) Red (1)."]),
X4_A(31,"Titration of sulfuric acid with sodium hydroxide",2,"<p>Dilute sulfuric acid and aqueous sodium hydroxide can be used to prepare sodium sulfate crystals using a method that involves titration. Dilute sulfuric acid is run from a burette into a conical flask containing 25.0 cm<sup>3</sup> of aqueous sodium hydroxide.</p><ol type='a'><li>Suggest why universal indicator is <b>not</b> suitable for this titration. [1]</li><li>Name an indicator that can be used in this titration. [1]</li></ol>",["(a) Universal indicator changes through a range of colours gradually, so it does not give a sharp end-point (1). Also the crystals would be contaminated with indicator.","(b) Methyl orange (or phenolphthalein) (1)."])
);

/* ---- Preparation of salts ---- */
const X4_B=(n,t,m,q,ms)=>P(t,m,q,ms,X4_S("Preparation of salts",n));
const X4_SALT13=TBL(["first salt solution","Co(NO<sub>3</sub>)<sub>2</sub>(aq)","AgNO<sub>3</sub>(aq)","Pb(NO<sub>3</sub>)<sub>2</sub>(aq)"],[["NaI(aq)","no change","yellow precipitate","yellow precipitate"],["Na<sub>2</sub>CO<sub>3</sub>(aq)","purple precipitate","yellow precipitate","white precipitate"],["Na<sub>2</sub>SO<sub>4</sub>(aq)","no change","white precipitate","white precipitate"]],520);
const X4_Q22T=TBL(["","step 1","step 2","step 3"],[["<b>A</b>","filter","evaporate the filtrate to dryness","leave the solid formed to cool"],["<b>B</b>","filter","evaporate the filtrate to the point of crystallisation","leave the filtrate to cool"],["<b>C</b>","filter","leave the residue in a warm place to dry","wash the residue with water"],["<b>D</b>","filter","wash the residue with water","leave the residue in a warm place to dry"]],520);
const X4_CuEq="<p style='text-align:center'>CuCO<sub>3</sub> + H<sub>2</sub>SO<sub>4</sub> + 4H<sub>2</sub>O → CuSO<sub>4</sub>.5H<sub>2</sub>O + CO<sub>2</sub></p>";
const X4_CuSteps="<p><b>step 1</b> Powdered solid copper(II) carbonate is added to 50.0 cm<sup>3</sup> of 0.05 mol / dm<sup>3</sup> sulfuric acid until the copper(II) carbonate is in excess.<br><b>step 2</b> The excess of copper(II) carbonate is separated from the aqueous copper(II) sulfate.<br><b>step 3</b> The aqueous copper(II) sulfate is heated until the solution is saturated.<br><b>step 4</b> The solution is allowed to cool and crystallise.<br><b>step 5</b> The crystals are removed and dried.</p>";
U[6].pp.push(
X4_B(1,"Making silver bromide by precipitation",5,"<p>Insoluble salts can be made by mixing solutions of two soluble salts.</p><p>A student followed the procedure shown to make silver bromide, an insoluble salt.</p><p><b>step 1</b> Add aqueous silver nitrate to a beaker. Then add aqueous potassium bromide and stir.<br><b>step 2</b> Filter the mixture formed in <b>step 1</b>.<br><b>step 3</b> Dry the residue</p><ol type='a'><li>State the term used to describe this method of making salts. [1]</li><li>Give the observation the student would make during <b>step 1</b>. [1]</li><li>Write the ionic equation for the reaction between aqueous silver nitrate and aqueous potassium bromide. Include state symbols. [3]</li></ol>",["(a) Precipitation (1).","(b) A cream (pale yellow) precipitate forms (1).","(c) Ag^+^(aq) + Br^−^(aq) → AgBr(s). Correct reactant ions (1); correct product AgBr (1); correct state symbols (1)."]),
X4_B(2,"Magnesium chloride from magnesium carbonate",5,"<p>A student prepares crystals of magnesium chloride by adding an excess of magnesium carbonate to 50.00 cm<sup>3</sup> of 2.00 mol / dm<sup>3</sup> hydrochloric acid.</p><p>The student filters the mixture and rinses the residue.</p><ol type='a'><li>Why does the student add an <b>excess</b> of magnesium carbonate? [1]</li><li>Why does the student rinse the residue? [1]</li><li>Describe how the student would obtain pure crystals of magnesium chloride from the filtrate. [3]</li></ol>",["(a) To make sure all the hydrochloric acid has reacted (is neutralised) (1).","(b) To wash any magnesium chloride solution off the residue, so it is not lost and the yield is higher (1).","(c) Heat the filtrate to evaporate some water until it is saturated (point of crystallisation) (1); leave it to cool so that crystals form (1); filter off the crystals and dry them between filter papers (1)."]),
X4_B(3,"Copper(II) carbonate in excess",2,"<p>Copper(II) sulfate crystals, CuSO<sub>4</sub>.5H<sub>2</sub>O, are hydrated.</p><p>Copper(II) sulfate crystals are made by reacting copper(II) carbonate with dilute sulfuric acid.</p><p>The equation for the overall process is shown.</p>"+X4_CuEq+X4_CuSteps+"<p>State <b>two</b> observations that would indicate that the copper(II) carbonate is in excess in <b>step 1</b>. [2]</p>",["Bubbling (effervescence) stops (1); some green solid copper(II) carbonate remains undissolved (1)."]),
X4_B(4,"Zinc sulfate from zinc carbonate",9,"<p>Dilute sulfuric acid is used to make salts known as sulfates.</p><p>A method consisting of three steps is used to make zinc sulfate from zinc carbonate.</p><p><b>step 1</b> Add an excess of zinc carbonate to 20 cm<sup>3</sup> of 0.4 mol / dm<sup>3</sup> dilute sulfuric acid until the reaction is complete.<br><b>step 2</b> Filter the mixture.<br><b>step 3</b> Heat the filtrate until a saturated solution forms and then allow it to crystallise.</p><ol type='a'><li>Name a suitable piece of apparatus for measuring 20 cm<sup>3</sup> of dilute sulfuric acid in <b>step 1</b>. [1]</li><li>State <b>two</b> observations which would show that the reaction is complete in <b>step 1</b>.<br>1<br>2 [2]</li><li>Why is it important to add an excess of zinc carbonate in <b>step 1</b>? [1]</li><li>What is meant by the term <i>saturated solution</i> in <b>step 3</b>? [2]</li><li>The equation for the reaction is shown.<br><span style='display:block;text-align:center'>ZnCO<sub>3</sub>(s) + H<sub>2</sub>SO<sub>4</sub>(aq) → ZnSO<sub>4</sub>(......) + H<sub>2</sub>O(l) + CO<sub>2</sub>(g)</span>Complete the equation by inserting the state symbol for zinc sulfate. [1]</li><li>Name another zinc compound which could be used to make zinc sulfate from dilute sulfuric acid using this method. [1]</li><li>Suggest why this method would <b>not</b> work to make barium sulfate from barium carbonate and dilute sulfuric acid. [1]</li></ol>",["(a) Measuring cylinder (or pipette or burette) (1).","(b) Effervescence (bubbling) stops (1); some solid zinc carbonate remains in the beaker (1).","(c) So that all the sulfuric acid is used up and none is left in the zinc sulfate (1).","(d) A solution containing the maximum amount of dissolved solute (1) at a given temperature (1).","(e) aq (1).","(f) Zinc oxide (or zinc hydroxide, or zinc) (1).","(g) Barium sulfate is insoluble, so it would coat the barium carbonate and could not be separated from the excess carbonate by filtration (1)."]),
X4_B(5,"Making copper(II) ethanoate",3,"<p>Ethanoic acid, CH<sub>3</sub>COOH, is a weak acid. It reacts with copper(II) carbonate to form the salt copper(II) ethanoate, Cu(CH<sub>3</sub>COO)<sub>2</sub>.</p><p>Describe how a crystalline sample of copper(II) ethanoate can be prepared starting with ethanoic acid and copper(II) carbonate. [3]</p>",["Add excess copper(II) carbonate to warm ethanoic acid and stir until bubbling stops (1); filter off the excess carbonate (1); heat the filtrate to the point of crystallisation, leave to cool, then filter and dry the crystals (1)."]),
X4_B(6,"Pure dry barium carbonate by precipitation",5,"<p>All sodium salts are soluble in water. All nitrates are soluble in water. Barium carbonate is insoluble in water.</p><p>Describe how you would make a pure, dry sample of barium carbonate by precipitation. Include:</p><ul><li>the names of the starting materials</li><li>full practical details</li><li>a chemical equation. [5]</li></ul>",["Starting materials: aqueous sodium carbonate and aqueous barium nitrate (1).","Mix the two solutions and stir; a white precipitate forms (1).","Filter to separate the precipitate (1).","Wash the residue with distilled water and dry it in a warm oven or between filter papers (1).","Equation: Na~2~CO~3~(aq) + Ba(NO~3~)~2~(aq) → BaCO~3~(s) + 2NaNO~3~(aq) (1)."]),
X4_B(7,"Iron(II) sulfate crystals from excess iron",3,"<p>A student investigated the reaction of lumps of iron with sulfuric acid.</p><p style='text-align:center'>Fe(s) + H<sub>2</sub>SO<sub>4</sub>(aq) → FeSO<sub>4</sub>(aq) + H<sub>2</sub>(g)</p><p>She used a conical flask containing lumps of iron and sulfuric acid, with the hydrogen gas collected in an upturned measuring cylinder over water.</p><p>Iron(II) sulfate can be prepared by adding excess iron to sulfuric acid.</p><p>Describe how you could obtain pure dry crystals of iron(II) sulfate from the reaction mixture in the conical flask. [3]</p>",["Filter the mixture to remove the excess iron (1); heat the filtrate to the point of crystallisation (to evaporate some water) and leave to cool so that crystals form (1); filter off the crystals and dry them between filter papers (1)."]),
X4_B(8,"Sodium citrate crystals",3,"<p>Citric acid reacts with sodium hydroxide to form the soluble salt sodium citrate.</p><p>Describe how you could prepare pure dry crystals of sodium citrate from citric acid and sodium hydroxide. [3]</p>",["Do a titration with an indicator to find the exact volume of citric acid that neutralises a measured volume of sodium hydroxide (1); repeat with the same volumes but no indicator (1); heat the solution to the point of crystallisation, leave to cool, filter off the crystals and dry them (1)."]),
X4_B(9,"Sodium ethanoate crystals",3,"<p>A student adds an aqueous solution of sodium hydroxide to an aqueous solution of ethanoic acid. She measures the temperature before and after the addition of sodium hydroxide: the temperature rises from 18 °C to 22 °C.</p><p>The product of the reaction is a salt called sodium ethanoate.</p><p>Describe how you would prepare pure, dry crystals of sodium ethanoate from a solution of sodium ethanoate in water. [3]</p>",["Heat the solution to evaporate some of the water until it is saturated (1); leave the hot saturated solution to cool so that crystals form (1); filter off the crystals and dry them between filter papers (1)."]),
X4_B(10,"Sodium hydroxide and sulfuric acid",2,"<p>Complete the word equation for the reaction of sodium hydroxide with sulfuric acid.</p><p style='text-align:center'>sodium hydroxide + sulfuric acid → ........ + ........ [2]</p>",["sodium sulfate (1) + water (1)."]),
X4_B(11,"Barium sulfate precipitation",3,"<p>Barium sulfate is an insoluble salt.</p><p>Barium sulfate can be made from aqueous ammonium sulfate using a precipitation reaction.</p><ol type='a'><li>Name a solution that can be added to aqueous ammonium sulfate to produce a precipitate of barium sulfate. [1]</li><li>Write an ionic equation for this precipitation reaction. Include state symbols. [2]</li></ol>",["(a) Aqueous barium chloride (or barium nitrate) (1).","(b) Ba^2+^(aq) + SO~4~^2−^(aq) → BaSO~4~(s). Correct ions and product (1); correct state symbols (1)."]),
X4_B(12,"Aluminium oxide and sodium hydroxide",1,"<p>Aluminium oxide reacts with dilute sodium hydroxide to form a salt and one other product.</p><p>Name the other product. [1]</p>",["Water (1): aluminium oxide is amphoteric, giving sodium aluminate and water."]),
X4_B(13,"Precipitation results table",6,"<p>Insoluble salts can be made by precipitation reactions.</p><p>A student mixed solutions of some soluble salts.</p><p>The results the student obtained are shown in the table.</p>"+X4_SALT13+"<p>All sodium salts are soluble in water. Use only results from the table to answer the following questions.</p><ol type='a'><li>Name:<br>(i) an insoluble cobalt salt [1]<br>(ii) an insoluble yellow lead salt [1]</li><li>Write the chemical equation for the reaction in which silver carbonate is formed. [2]</li><li>Write the ionic equation for the reaction in which lead(II) iodide is formed. [2]</li></ol>",["(a)(i) Cobalt(II) carbonate (1).","(a)(ii) Lead(II) iodide (1).","(b) 2AgNO~3~ + Na~2~CO~3~ → Ag~2~CO~3~ + 2NaNO~3~. Correct formulae (1); balanced (1).","(c) Pb^2+^(aq) + 2I^−^(aq) → PbI~2~(s). Correct species and balance (1); correct state symbols (1)."]),
X4_B(14,"Aluminium oxide and sulfuric acid",2,"<p>Aluminium oxide reacts with dilute sulfuric acid to form a salt.</p><p>State the name and write the formula of the salt formed.<br>name ........<br>formula ........ [2]</p>",["Name: aluminium sulfate (1).","Formula: Al~2~(SO~4~)~3~ (1)."]),
X4_B(15,"Less than the maximum mass of crystals",1,"<p>Copper(II) sulfate crystals, CuSO<sub>4</sub>.5H<sub>2</sub>O, are hydrated.</p><p>Copper(II) sulfate crystals are made by reacting copper(II) carbonate with dilute sulfuric acid.</p><p>The equation for the overall process is shown.</p>"+X4_CuEq+X4_CuSteps+"<p><b>Steps 1–5</b> were done correctly but the mass of crystals obtained was less than the maximum mass.</p><p>Explain why. [1]</p>",["Some copper(II) sulfate remained dissolved in the solution (mother liquor) after crystallisation, so it was not collected as crystals (1)."]),
X4_B(16,"Copper(II) sulfate crystals: steps explained",6,"<p>Copper(II) sulfate crystals, CuSO<sub>4</sub>.5H<sub>2</sub>O, are hydrated.</p><p>Copper(II) sulfate crystals are made by reacting copper(II) carbonate with dilute sulfuric acid.</p><p>The equation for the overall process is shown.</p>"+X4_CuEq+X4_CuSteps+"<ol type='a'><li>Name a different substance, other than copper(II) carbonate, that could be added to dilute sulfuric acid to produce copper(II) sulfate in <b>step 1</b>. [1]</li><li>Name the process used to separate the aqueous copper(II) sulfate from the excess of copper(II) carbonate in <b>step 2</b>. [1]</li><li>The solution of aqueous copper(II) sulfate was heated until it was saturated in <b>step 3</b>.<br>(i) Suggest what is meant by the term <i>saturated solution</i>. [2]<br>(ii) What evidence would show that the solution was saturated in <b>step 3</b>? [1]<br>(iii) Why should the aqueous copper(II) sulfate <b>not</b> be heated to dryness in <b>step 3</b>? [1]</li></ol>",["(a) Copper(II) oxide (or copper(II) hydroxide) (1).","(b) Filtration (1).","(c)(i) A solution containing the maximum amount of dissolved solute (1) at a particular temperature (1).","(c)(ii) Crystals form on a cold glass rod dipped into the solution and removed (1).","(c)(iii) Heating to dryness would drive off the water of crystallisation, so the crystals would no longer be hydrated (1)."]),
X4_B(17,"Lead(II) iodide by precipitation",5,"<p>This question is about salts.</p><p>Salts that are insoluble in water are made by precipitation.</p><ul><li>Lead(II) iodide, PbI<sub>2</sub>, is insoluble in water.</li><li>All nitrates are soluble in water.</li><li>All sodium salts are soluble in water.</li></ul><p>You are provided with solid lead(II) nitrate, Pb(NO<sub>3</sub>)<sub>2</sub>, and solid sodium iodide, NaI.</p><p>Describe how you would make a pure sample of lead(II) iodide by precipitation.</p><p>Your answer should include:</p><ul><li>practical details</li><li>a chemical equation for the precipitation reaction. [5]</li></ul>",["Dissolve each solid separately in distilled water (1).","Mix the two solutions and stir; a yellow precipitate of lead(II) iodide forms (1).","Filter the mixture (1).","Wash the residue with distilled water and dry it in a warm place or between filter papers (1).","Equation: Pb(NO~3~)~2~ + 2NaI → PbI~2~ + 2NaNO~3~ (1)."]),
X4_B(18,"Zinc sulfate crystals from zinc carbonate",5,"<p>This question is about salts.</p><p>Salts that are soluble in water can be made by the reaction between insoluble carbonates and dilute acids. Zinc sulfate is soluble in water.</p><p>You are provided with solid zinc carbonate, ZnCO<sub>3</sub>, and dilute sulfuric acid, H<sub>2</sub>SO<sub>4</sub>.</p><p>Describe how you would make a pure sample of zinc sulfate crystals.</p><p>Your answer should include:</p><ul><li>practical details</li><li>how you would make sure that all the dilute sulfuric acid has reacted</li><li>a chemical equation for the reaction. [5]</li></ul>",["Add zinc carbonate in small portions to warm dilute sulfuric acid, stirring until no more dissolves and bubbling stops, so some solid is left (excess) and all the acid has reacted (1).","Filter off the excess zinc carbonate (1).","Heat the filtrate to evaporate some water to the point of crystallisation and leave it to cool and crystallise (1).","Filter off the crystals and dry them between filter papers (1).","Equation: ZnCO~3~ + H~2~SO~4~ → ZnSO~4~ + H~2~O + CO~2~ (1)."]),
X4_B(19,"Word equation: ethanoic acid and copper(II) carbonate",1,"<p>Ethanoic acid, CH<sub>3</sub>COOH, is a weak acid. It reacts with copper(II) carbonate to form the salt copper(II) ethanoate, Cu(CH<sub>3</sub>COO)<sub>2</sub>.</p><p>Write the word equation for the reaction between ethanoic acid and copper(II) carbonate. [1]</p>",["ethanoic acid + copper(II) carbonate → copper(II) ethanoate + water + carbon dioxide (1)."]),
X4_B(20,"Acid giving an insoluble salt (multiple choice)",1,"<p>Which substance reacts with dilute sulfuric acid to form a salt that can be removed from the resulting mixture by filtration?</p><p><b>A</b> aqueous barium chloride<br><b>B</b> aqueous sodium hydroxide<br><b>C</b> copper<br><b>D</b> copper(II) carbonate [1]</p>",["A (1): barium chloride gives insoluble barium sulfate, which can be filtered off. The other three give soluble salts (or no reaction)."]),
X4_B(21,"Lead(II) azide",5,"<p>Lead(II) azide is insoluble in water. Solid lead(II) azide can be made in a precipitation reaction between aqueous lead(II) nitrate and aqueous sodium azide.</p><p>Lead(II) azide has the formula Pb(N<sub>3</sub>)<sub>2</sub>.</p><ol type='a'><li>Deduce the formula of the azide ion. [1]</li><li>Complete the chemical equation for the reaction between aqueous lead(II) nitrate and aqueous sodium azide to form solid lead(II) azide and aqueous sodium nitrate. Include state symbols.<br><span style='display:block;text-align:center'>Pb(NO<sub>3</sub>)<sub>2</sub>(aq) + ....... NaN<sub>3</sub>(aq) → Pb(N<sub>3</sub>)<sub>2</sub>(.....) + ....... ..................(.....)</span> [2]</li><li>Describe how you could obtain a sample of lead(II) azide that is <b>not</b> contaminated with any soluble salts from the reaction mixture. [2]</li></ol>",["(a) N~3~^−^ (1): lead is Pb^2+^ and the formula has two azide ions.","(b) Pb(NO~3~)~2~(aq) + 2NaN~3~(aq) → Pb(N~3~)~2~(s) + 2NaNO~3~(aq). Coefficients 2 and 2NaNO~3~ (1); state symbols (s) and (aq) (1).","(c) Filter the mixture and wash the residue with distilled water (1); dry the residue (1)."]),
X4_B(22,"Order of steps for dry barium sulfate (multiple choice)",1,"<p>Barium sulfate is an insoluble salt.</p><p>It can be made by reacting copper(II) sulfate solution with barium nitrate solution.</p><p style='text-align:center'>CuSO<sub>4</sub>(aq) + Ba(NO<sub>3</sub>)<sub>2</sub>(aq) → Cu(NO<sub>3</sub>)<sub>2</sub>(aq) + BaSO<sub>4</sub>(s)</p><p>What is the correct order of steps to obtain a pure, dry sample of barium sulfate from the reaction mixture? [1]</p>"+X4_Q22T,["D (1): filter, wash the residue with water to remove soluble copper(II) nitrate, then dry the residue in a warm place."]),
X4_B(23,"Acid and base to make calcium chloride",2,"<p>Calcium chloride, CaC<i>l</i><sub>2</sub>, is a salt.</p><p>Suggest the name of an acid and a base that would react together to make calcium chloride.<br>acid ........<br>base ........ [2]</p>",["Acid: hydrochloric acid (1).","Base: calcium hydroxide (or calcium oxide, or calcium carbonate) (1)."]),
X4_B(24,"Hydrated copper(II) sulfate from copper(II) oxide",3,"<p>Describe how you could prepare a pure sample of crystals of hydrated copper(II) sulfate using dilute sulfuric acid and an excess of copper(II) oxide. [3]</p>",["Add excess copper(II) oxide to warm dilute sulfuric acid and stir (1); filter to remove the excess copper(II) oxide (1); heat the filtrate to the point of crystallisation, leave to cool, filter off the crystals and dry them between filter papers (1)."]),
X4_B(25,"Order of steps: aluminium sulfate",2,"<p>The following statements are about the procedure for making crystals of hydrated aluminium sulfate from aluminium hydroxide and sulfuric acid.</p><p><b>A</b> Filter off the excess aluminium hydroxide.<br><b>B</b> Filter off the crystals and dry between filter papers.<br><b>C</b> Warm the filtrate to the point of crystallisation.<br><b>D</b> Add aluminium hydroxide to warm dilute sulfuric acid and stir.<br><b>E</b> Leave the mixture at room temperature to form more crystals.<br><b>F</b> Add more aluminium hydroxide to the sulfuric acid until the aluminium hydroxide is in excess.</p><p>Put the statements <b>A</b>, <b>B</b>, <b>C</b>, <b>D</b>, <b>E</b> and <b>F</b> in the correct order. The first one has been done for you: <b>D</b>, ..., ..., ..., ..., ... [2]</p>",["Correct order: D, F, A, C, E, B. D, F and A in the right order (1); C, E and B in the right order (1)."]),
X4_B(26,"Order of steps: zinc sulfate from zinc",2,"<p>The following statements are about the procedure for making crystals of hydrated zinc sulfate from zinc and dilute sulfuric acid.</p><p><b>A</b> Warm the mixture until no more bubbles are seen.<br><b>B</b> Add excess zinc to dilute sulfuric acid.<br><b>C</b> Warm the filtrate to the point of crystallisation.<br><b>D</b> Leave the mixture at room temperature to form more crystals.<br><b>E</b> Filter off the excess zinc.<br><b>F</b> Filter off the crystals and dry between filter papers.</p><p>Put the statements <b>A</b>, <b>B</b>, <b>C</b>, <b>D</b>, <b>E</b> and <b>F</b> in the correct order. The first one has been done for you: <b>B</b>, ..., ..., ..., ..., ... [2]</p>",["Correct order: B, A, E, C, D, F. B, A and E in the right order (1); C, D and F in the right order (1)."]),
X4_B(27,"Order of steps: magnesium chloride from magnesium",2,"<p>The following statements are about the procedure for making crystals of hydrated magnesium chloride from magnesium and dilute hydrochloric acid.</p><p><b>A</b> Leave the mixture until no more bubbles are seen.<br><b>B</b> Leave the mixture at room temperature to form more crystals.<br><b>C</b> Add an excess of magnesium to dilute hydrochloric acid.<br><b>D</b> Warm the filtrate to the point of crystallisation.<br><b>E</b> Filter off the crystals and dry between filter papers.<br><b>F</b> Filter off the excess magnesium.</p><p>Put the statements <b>A</b>, <b>B</b>, <b>C</b>, <b>D</b>, <b>E</b> and <b>F</b> in the correct order. The first one has been done for you: <b>C</b>, ..., ..., ..., ..., ... [2]</p>",["Correct order: C, A, F, D, B, E. C, A and F in the right order (1); D, B and E in the right order (1)."]),
X4_B(28,"Silver chloride by precipitation",5,"<p>Silver chloride, AgC<i>l</i>, is insoluble. It can be made by a precipitation reaction between aqueous barium chloride and a suitable aqueous silver salt.</p><ol type='a'><li>What is meant by the term <i>precipitate</i>? [2]</li><li>Complete the chemical equation to show the formation of insoluble silver chloride from aqueous barium chloride and a suitable silver salt. Name the silver salt you have chosen for the preparation of silver chloride.<br><span style='display:block;text-align:center'>BaC<i>l</i><sub>2</sub> + .................. → .................. + ..................</span>name of suitable silver salt ........ [3]</li></ol>",["(a) An insoluble solid (1) that forms when two solutions react (and separates from the solution) (1).","(b) Silver nitrate (1). BaCl~2~ + 2AgNO~3~ → 2AgCl + Ba(NO~3~)~2~: correct formulae (1); balanced (1)."]),
X4_B(29,"Titrating dilute acid with sodium hydroxide",4,"<p>The concentration of a dilute acid can be found by reacting it with aqueous sodium hydroxide. Aqueous sodium hydroxide is run from a burette into a conical flask containing dilute acid.</p><ol type='a'><li>What piece of apparatus should be used to add exactly 25.0 cm<sup>3</sup> of dilute acid to the conical flask? [1]</li><li>A few drops of litmus solution are added to the conical flask.<br>Explain why litmus solution is added to the conical flask. [1]</li><li>Aqueous sodium hydroxide is then added to the dilute acid until it is in excess.<br>Describe the change in the colour of the litmus solution in the conical flask.<br>from ........ to ........ [2]</li></ol>",["(a) A (25.0 cm^3^) pipette (1).","(b) It is an indicator, which shows when the acid has been neutralised (the end-point) (1).","(c) From red (1) to blue (1)."]),
X4_B(30,"Sodium sulfate crystals after a titration",5,"<p>Dilute sulfuric acid and aqueous sodium hydroxide can be used to prepare sodium sulfate crystals using a method that involves titration. Dilute sulfuric acid is run from a burette into a conical flask containing 25.0 cm<sup>3</sup> aqueous sodium hydroxide.</p><p>20.0 cm<sup>3</sup> of dilute sulfuric acid neutralises 25.0 cm<sup>3</sup> of 1.00 mol / dm<sup>3</sup> aqueous sodium hydroxide.</p><p>At the end of the titration the conical flask contains aqueous sodium sulfate with the dissolved indicator as an impurity.</p><p>Describe how to prepare a pure sample of sodium sulfate crystals from the original solutions of dilute sulfuric acid and aqueous sodium hydroxide of the same concentrations.</p><p><b>You are not required to give details of how to carry out the titration.</b> [5]</p>",["Mix 25.0 cm^3^ of aqueous sodium hydroxide with 20.0 cm^3^ of the dilute sulfuric acid, with no indicator (1).","Heat the solution to evaporate some of the water until it is saturated (point of crystallisation) (1).","Leave the solution to cool so that crystals form (1).","Filter off the crystals (1).","Wash with a little cold distilled water and dry between filter papers (1)."]),
X4_B(31,"Dissolving and precipitation terms",2,"<p>A solution is a mixture of a solute and a solvent.</p><ol type='a'><li>Name the process when a solid substance mixes with a solvent to form a solution. [1]</li><li>Name the type of reaction when two solutions react to form an insoluble substance. [1]</li></ol>",["(a) Dissolving (1).","(b) Precipitation (1)."]),
X4_B(32,"Water of crystallisation: barium chloride",2,"<p>Some chlorides are hydrated.</p><p>When hydrated barium chloride crystals, BaC<i>l</i><sub>2</sub>•<i>x</i>H<sub>2</sub>O, are heated they give off water.</p><p style='text-align:center'>BaC<i>l</i><sub>2</sub>•<i>x</i>H<sub>2</sub>O(s) → BaC<i>l</i><sub>2</sub>(s) + <i>x</i>H<sub>2</sub>O(g)</p><p>A student carries out an experiment to determine the value of <i>x</i> in BaC<i>l</i><sub>2</sub>•<i>x</i>H<sub>2</sub>O.</p><p><b>step 1</b> Hydrated barium chloride crystals are weighed.<br><b>step 2</b> The hydrated barium chloride crystals are then heated.<br><b>step 3</b> The remaining solid is weighed.</p><p>Describe how the student can be sure that all the water is given off. [2]</p>",["Heat again (and let it cool) then reweigh the solid (1); repeat until the mass no longer changes (constant mass) (1)."]),
X4_B(33,"Water of crystallisation: sodium sulfate",2,"<p>Some sulfates are hydrated.</p><p>When hydrated sodium sulfate crystals, Na<sub>2</sub>SO<sub>4</sub>•<i>x</i>H<sub>2</sub>O, are heated, they give off water.</p><p style='text-align:center'>Na<sub>2</sub>SO<sub>4</sub>•<i>x</i>H<sub>2</sub>O(s) → Na<sub>2</sub>SO<sub>4</sub>(s) + <i>x</i>H<sub>2</sub>O(g)</p><p>A student carries out an experiment to determine the value of <i>x</i> in Na<sub>2</sub>SO<sub>4</sub>•<i>x</i>H<sub>2</sub>O.</p><p><b>step 1</b> Hydrated sodium sulfate crystals are weighed.<br><b>step 2</b> The hydrated sodium sulfate crystals are then heated.<br><b>step 3</b> The remaining solid is weighed.</p><p>Describe how the student can check that all the water has been given off. [2]</p>",["Heat the solid again, cool and reweigh (1); repeat until the mass stays the same (constant mass) (1)."])
);

/* ---- Types of oxides ---- */
const X4_C=(n,t,m,q,ms)=>P(t,m,q,ms,X4_S("Types of oxides",n));
const X4_OX3=TBL(["element","melting point / °C","density in g / cm<sup>3</sup>","electrical conductivity of the solid","atomic radius / nm"],[["<b>P</b>","1535","7.86","very good","0.125"],["<b>Q</b>","–7","3.12","does not conduct","0.114"],["<b>R</b>","1495","8.90","very good","0.126"],["<b>S</b>","–157","0.0035","does not conduct","0.110"],["<b>T</b>","839","1.54","very good","0.174"]],540);
U[6].pp.push(
X4_C(1,"Showing zinc oxide is amphoteric",3,"<p>Zinc oxide is amphoteric.</p><p>Describe <b>two</b> simple experiments to show that zinc oxide is amphoteric. Name the reagents you would use and describe the observations you would make.</p><p>reagent 1 ........<br>observation ........<br>reagent 2 ........<br>observation ........ [3]</p>",["Reagent 1: dilute acid, e.g. dilute hydrochloric acid; reagent 2: aqueous sodium hydroxide (1).","Observation with the acid: the white solid dissolves to give a colourless solution (1).","Observation with the alkali: the white solid dissolves to give a colourless solution (1)."]),
X4_C(2,"Sodium hydrogen sulfate solution: tests",3,"<p>Aqueous sodium hydrogen sulfate, NaHSO<sub>4</sub>(aq), contains the ions Na<sup>+</sup>(aq), H<sup>+</sup>(aq) and SO<sub>4</sub><sup>2–</sup>(aq).</p><p>Describe what you would see if the following experiments were done.</p><ol type='a'><li>A flame test was done on aqueous sodium hydrogen sulfate. [1]</li><li>Solid copper(II) oxide was added to aqueous sodium hydrogen sulfate and the mixture was warmed. [2]</li></ol>",["(a) Yellow flame (1).","(b) The black solid dissolves (1); a blue solution forms (1)."]),
X4_C(3,"Properties of elements P to T",4,"<p>This question is about elements in the Periodic Table.</p><p>(a) The table shows some properties of five elements, <b>P</b>, <b>Q</b>, <b>R</b>, <b>S</b> and <b>T</b>.</p>"+X4_OX3+"<p>Use only the elements shown in the table to answer this question.</p><p>State which <b>two</b> of the elements, <b>P</b>, <b>Q</b>, <b>R</b>, <b>S</b> and <b>T</b>, are covalent molecules. Give <b>two</b> reasons for your answer.<br>elements ........ and ........<br>reason 1 ........<br>reason 2 ........ [3]</p><p>(b) Element <b>T</b> is on the left-hand side of the Periodic Table. Suggest whether its oxide is acidic or basic. Give a reason for your answer. [1]</p>",["(a) Elements Q and S (1); reason 1: low melting points (1); reason 2: do not conduct electricity (as solids) (1).","(b) Basic (1): T is a metal, and metal oxides are basic."]),
X4_C(4,"Classifying oxides",2,"<p>Oxides can be classified as acidic, amphoteric, basic or neutral.</p><p>Classify each of these oxides:<br>sodium oxide ........<br>silicon(IV) oxide ........ [2]</p>",["Sodium oxide: basic (1).","Silicon(IV) oxide: acidic (1)."]),
X4_C(5,"Phosphorus(V) oxide",1,"<p>Phosphorus burns in oxygen to form phosphorus(V) oxide.</p><p>Is phosphorus(V) oxide an acidic oxide or a basic oxide? Give a reason for your answer. [1]</p>",["Acidic (1): it is the oxide of a non-metal (it reacts with water to form an acid / reacts with alkalis)."]),
X4_C(6,"Lithium and water",3,"<p>When lithium reacts with water, hydrogen is produced and the solution formed is alkaline.</p><ol type='a'><li>Balance the chemical equation for this reaction.<br><span style='display:block;text-align:center'>........Li + ........H<sub>2</sub>O → 2LiOH + H<sub>2</sub></span> [2]</li><li>Give the name of the product which causes the solution to be alkaline. [1]</li></ol>",["(a) 2Li + 2H~2~O → 2LiOH + H~2~: coefficient 2 for Li (1); coefficient 2 for H~2~O (1).","(b) Lithium hydroxide (1)."]),
X4_C(7,"Sodium and water: alkaline solution",3,"<p>When sodium reacts with water, an alkaline solution is formed.</p><p style='text-align:center'>2Na + 2H<sub>2</sub>O → 2NaOH + H<sub>2</sub></p><ol type='a'><li>Use the information in the equation to explain why the solution formed is alkaline. [1]</li><li>Describe how you could use a named indicator solution to show that the solution is alkaline. [2]</li></ol>",["(a) Sodium hydroxide (OH^−^ ions) is formed (1).","(b) Add universal indicator solution (or litmus) (1); it turns blue or purple (litmus turns blue) (1)."]),
X4_C(8,"Universal indicator and sodium oxide",2,"<p>Universal indicator is added to an aqueous solution of sodium oxide.</p><ul><li>What colour change is observed? from green to ........</li><li>Give a reason for your answer. [2]</li></ul>",["Colour: purple (or blue) (1).","Reason: sodium oxide is a basic oxide, which forms an alkaline solution (sodium hydroxide) in water (1)."]),
X4_C(9,"Thermal decomposition of copper(II) nitrate",3,"<p>Copper(II) nitrate decomposes when heated. Two gases, oxygen and nitrogen dioxide, and a solid are made in the reaction.</p><p>A sample of copper(II) nitrate was decomposed by heating it in a test tube. The gases pass through a tube of aqueous sodium hydroxide, and the gas that is not absorbed, <b>X</b>, is collected over water in an upturned test tube.</p><ol type='a'><li>Complete the chemical equation for the reaction.<br><span style='display:block;text-align:center'>2Cu(NO<sub>3</sub>)<sub>2</sub> → O<sub>2</sub> + ............NO<sub>2</sub> + ..............................</span> [2]</li><li>Only oxygen gas is collected at <b>X</b>. Explain why. [1]</li></ol>",["(a) 2Cu(NO~3~)~2~ → O~2~ + 4NO~2~ + 2CuO: 4NO~2~ (1); 2CuO (1).","(b) Nitrogen dioxide is an acidic oxide, so it reacts with (is absorbed by) the aqueous sodium hydroxide, but oxygen does not (1)."]),
X4_C(10,"Sodium hydrogensulfate solution X",4,"<p>Sodium hydrogensulfate, NaHSO<sub>4</sub>, dissolves in water to produce an aqueous solution, <b>X</b>, containing Na<sup>+</sup>, H<sup>+</sup> and SO<sub>4</sub><sup>2–</sup> ions.</p><p>State the observations when the following tests are done.</p><ol type='a'><li>A flame test is carried out on <b>X</b>. [1]</li><li>Copper(II) oxide is warmed with an excess of <b>X</b>. [2]</li><li>Acidified aqueous barium nitrate is added to <b>X</b>. [1]</li></ol>",["(a) Yellow flame (1).","(b) The black solid dissolves (1); a blue solution forms (1).","(c) A white precipitate forms (1)."]),
X4_C(11,"Term for an oxide reacting with acids and alkalis",1,"<p>Aluminium oxide reacts with acids and with alkalis.</p><p>What term is used to describe an oxide that reacts with acids and with alkalis? [1]</p>",["Amphoteric (1)."]),
X4_C(12,"Electrolysis of concentrated hydrochloric acid",4,"<p>This question is about electrolysis.</p><p>Concentrated hydrochloric acid is electrolysed using two carbon electrodes connected to a power supply and dipping into the acid in a beaker.</p><ol type='a'><li>Chloride ions are discharged at the anode.<br>(i) Complete the ionic half-equation for this reaction.<br><span style='display:block;text-align:center'>........C<i>l</i><sup>–</sup>(aq) → ........(g) + ........e<sup>–</sup></span> [2]<br>(ii) State whether oxidation or reduction takes place. Explain your answer. [1]</li><li>Describe what is seen at the cathode. [1]</li></ol>",["(a)(i) 2Cl^−^(aq) → Cl~2~(g) + 2e^−^: coefficient 2 and Cl~2~ (1); 2 electrons (1).","(a)(ii) Oxidation (1): the chloride ions lose electrons.","(b) Bubbles (effervescence) of a colourless gas, hydrogen (1)."])
);

/* ---- Periodic Table: group properties ---- */
const X4_D=(n,t,m,q,ms)=>P(t,m,q,ms,X4_S("Periodic Table and group properties",n));
if(!COVM.F2)COVM.F2=["Fluorine, F~2~","Each fluorine atom has three non-bonding pairs and shares one pair.",[["F",-1,0,0,"d",3],["F",0,0,1,"x",3]]];
