const X4_Q7=TBL(["structure","description"],[["<b>A</b>","a molecule with two bromine atoms joined by a single bond, Br–Br"],["<b>B</b>","a giant ionic lattice of alternating Na<sup>+</sup> and Br<sup>–</sup> ions"],["<b>C</b>","a molecule with one bromine atom bonded to three fluorine atoms (F–Br–F with a third F on bromine), BrF<sub>3</sub>"],["<b>D</b>","ethene, H<sub>2</sub>C=CH<sub>2</sub>"],["<b>E</b>","1,2-dibromoethane, Br–CH<sub>2</sub>–CH<sub>2</sub>–Br"]],560);
