const X4_Q32=TBL(["particle","number of electrons","number of neutrons","number of protons","electronic structure","charge on particle"],[["<b>A</b>","11","12","11","2,8,1","0"],["<b>B</b>",X4_BL,"14","11","2,8,1","0"],["<b>C</b>","18","20",X4_BL,"2,8,8","0"],["<b>D</b>","18","20","17",X4_BL,X4_BL]],560);
const X4_Q33=TBL(["element","boiling point / °C","atomic radius / pm","relative thermal conductivity","observations when it reacts with cold water"],[["sodium","883","186","3.9","rapid bubbling but does <b>not</b> burst into flame"],["potassium","759","227",X4_BL,"very rapid bubbling and bursts into flame"],["rubidium","688",X4_BL,"1.6",X4_BL],["caesium","671","265","1.0","explodes"]],560);
