const X4_ENG=()=>`<figure class="fig" style="max-width:300px"><svg viewBox="0 0 260 170" role="img" aria-label="Energy level diagram: reactants at a higher energy than products" style="width:100%;height:auto"><g fill="none" stroke="currentColor" stroke-width="1.6"><path d="M50 12V140H240"/><path d="M50 36H130"/><path d="M130 36V104" /><path d="M130 104H210"/></g><path d="M130 104l-5-9h10z" fill="currentColor"/><path d="M50 12l-4 9h8zM240 140l-9-4v8z" fill="currentColor"/><g fill="currentColor" font-size="11" text-anchor="middle"><text x="90" y="30">reactants</text><text x="170" y="120">products</text><text x="145" y="160">progress of reaction</text><text transform="translate(20 80) rotate(-90)">energy</text></g></svg><figcaption>Energy level diagram for the reaction</figcaption></figure>`;
U[7].pp.push(
X4_D(1,"Physical properties: transition elements vs Group I",2,"<p>Give two physical properties shown by transition elements which are <b>not</b> shown by Group I elements.<br>1 ........<br>2 ........ [2]</p>",["Any two of: higher melting point (1); higher density (1); harder / stronger (1)."]),
X4_D(2,"Trend in reactivity of Group I",1,"<p>Describe the trend in the reactivity of Group I elements. [1]</p>",["Reactivity increases down the group (1)."]),
X4_D(3,"Copper as a transition element",2,"<p>Copper is a transition element. It can have variable oxidation states.</p><p>State <b>two</b> other chemical properties of transition elements which make them different from Group I elements.<br>1 ........<br>2 ........ [2]</p>",["Any two of: forms coloured compounds (1); acts as a catalyst (1); less reactive (e.g. with water or oxygen) (1)."]),
X4_D(4,"Nickel compounds vs sodium compounds",1,"<p>Predict <b>one</b> difference in the appearance of aqueous solutions of nickel compounds compared to aqueous solutions of sodium compounds. [1]</p>",["Nickel compounds give coloured (e.g. green) solutions, but sodium compounds give colourless solutions (1)."]),
X4_D(5,"Green gas in Period 3",1,"<p>This question is about the elements in Period 3 of the Periodic Table.</p><p style='text-align:center'><b>Na &nbsp; Mg &nbsp; Al &nbsp; Si &nbsp; P &nbsp; S &nbsp; Cl &nbsp; Ar</b></p><p>State which Period 3 element is a green gas at room temperature and pressure. [1]</p>",["Chlorine (Cl) (1)."]),
X4_D(6,"Two ways transition elements differ from Group I",2,"<p>Give <b>two</b> ways in which the properties of transition elements differ from the properties of Group I metals.<br>1 ........<br>2 ........ [2]</p>",["Any two of: higher melting point (1); higher density (1); harder (1); form coloured compounds (1); act as catalysts (1); variable oxidation states (1); less reactive (1)."]),
X4_D(7,"Structure with two different halogens",1,"<p>The following describes the structures of five substances, <b>A</b>, <b>B</b>, <b>C</b>, <b>D</b> and <b>E</b>.</p>"+X4_Q7+"<p>Which structure, <b>A</b>, <b>B</b>, <b>C</b>, <b>D</b> or <b>E</b>, contains atoms of <b>two</b> different halogens? [1]</p>",["C (1): BrF~3~ contains bromine and fluorine."]),
X4_D(8,"Boiling points of Group V chlorides",3,"<p>Group V chlorides are covalent molecules. The boiling points of some Group V chlorides are shown.</p>"+X4_Q8+"<ol type='a'><li>Suggest the approximate boiling point of PC<i>l</i><sub>3</sub>. [1]</li><li>Explain the trend in boiling points in terms of attractive forces between particles. [2]</li></ol>",["(a) Any value between 71 and 130 °C (1); about 75–100 °C is sensible.","(b) The molecules get larger (heavier) down the group, so the forces of attraction between the molecules increase (1); more energy is needed to overcome these forces, so the boiling point rises (1)."]),
X4_D(9,"Chlorine and potassium bromide",4,"<p>When chlorine reacts with aqueous potassium bromide a displacement reaction occurs.</p><ol type='a'><li>Describe the colour change of the solution.<br>from ........ to ........ [2]</li><li>Write a chemical equation for this reaction. [2]</li></ol>",["(a) From colourless (1) to orange (or brown) (1).","(b) Cl~2~ + 2KBr → 2KCl + Br~2~. Correct formulae (1); balanced (1)."]),
X4_D(10,"Fluorine, a Group VII element",6,"<p>Fluorine is a Group VII element. Fluorine forms compounds with metals and non-metals.</p><ol type='a'><li>Predict the physical state of fluorine at room temperature and pressure. [1]</li><li>Fluorine exists as diatomic molecules.<br>Complete the dot-and-cross diagram to show the electron arrangement in a molecule of fluorine. Show outer shell electrons only. [2]"+FBLANK("F2","Outline of the fluorine molecule")+"</li><li>Write a chemical equation for the reaction between sodium and fluorine. [2]</li><li>Explain why chlorine does <b>not</b> react with aqueous sodium fluoride. [1]</li></ol>",["(a) Gas (1).","(b) A shared pair of electrons (one dot and one cross) in the overlap (1); three non-bonding pairs on each fluorine atom, so each has eight outer electrons (1).","(c) 2Na + F~2~ → 2NaF. Correct formulae (1); balanced (1).","(d) Chlorine is less reactive than fluorine, so it cannot displace fluorine from sodium fluoride (1)."]),
X4_D(11,"Extracting titanium",3,"<p>Titanium is extracted from an ore called rutile. Rutile is an impure form of titanium(IV) oxide, TiO<sub>2</sub>.</p><p>Rutile is mixed with coke and heated in a furnace through which chlorine gas is passed. The product is gaseous titanium(IV) chloride, TiC<i>l</i><sub>4</sub>.</p><p>Titanium(IV) chloride is heated with an excess of magnesium, in an atmosphere of argon.</p><ol type='a'><li>Balance the chemical equation for the reaction.<br><span style='display:block;text-align:center'>TiC<i>l</i><sub>4</sub> + ........Mg → Ti + ........MgC<i>l</i><sub>2</sub></span> [1]</li><li>Titanium(IV) chloride can be reacted with sodium instead of magnesium.<br>The reaction between titanium(IV) chloride and sodium is similar to the reaction between titanium(IV) chloride and magnesium.<br>Write a chemical equation for the reaction between titanium(IV) chloride and sodium. [1]</li><li>Suggest why the reaction between titanium(IV) chloride and magnesium is done in an atmosphere of argon and <b>not</b> in air. [1]</li></ol>",["(a) TiCl~4~ + 2Mg → Ti + 2MgCl~2~ (1).","(b) TiCl~4~ + 4Na → Ti + 4NaCl (1).","(c) Argon is unreactive, so it stops the hot magnesium (and titanium) reacting with oxygen (or nitrogen) in the air (1)."]),
X4_D(12,"Trends across a period",4,"<p>Across a period, the elements change from metallic to non-metallic.</p><ol type='a'><li>Describe how the type of oxide changes across this period. [2]</li><li>Describe how the type of bonding in the chlorides formed by these elements changes across this period. [2]</li></ol>",["(a) Oxides change from basic (metals) (1) through amphoteric to acidic (non-metals) (1).","(b) Chlorides change from ionic (metal chlorides) (1) to covalent (non-metal chlorides) (1)."]),
X4_D(13,"Group I data table: rubidium and potassium",5,"<p>The table shows some properties of four Group I elements.</p>"+X4_Q13+"<ol type='a'><li>(i) Complete the table by predicting:<br>• the boiling point of rubidium<br>• the atomic radius of potassium. [2]<br>(ii) Describe the trend in the melting point of the Group I elements down the group. [1]<br>(iii) Deduce the physical state of potassium at 60 °C. Explain your answer. [2]</li></ol>",["(a)(i) Boiling point of rubidium: any value between 671 and 760 °C (1); atomic radius of potassium: any value between 0.191 and 0.250 nm, about 0.22 nm (1).","(a)(ii) Melting point decreases down the group (1).","(a)(iii) Solid (1); 60 °C is below the melting point of potassium, 63 °C (1)."]),
X4_D(14,"Valency electrons and valency in Period 3",7,"<p>In the Periodic Table, the elements are arranged in columns called Groups and in rows called Periods.</p><ol type='a'><li>Complete the table for some of the elements in Period 3. [2]</li></ol>"+X4_Q14+"<ol type='a' start='2'><li>What is the relationship between the group number and the number of valency electrons? [1]</li><li>Explain the relationship between the number of valency electrons and the valency<br>for the elements Na to Al,<br>for the elements P to C<i>l</i>. [4]</li></ol>",["(a) Number of valency electrons: 1, 2, 3, 4, 5, 6, 7 (1); valency: 1, 2, 3, 4, 3, 2, 1 (1).","(b) The group number equals the number of valency electrons (1).","(c) Na to Al: the valency equals the number of valency electrons (1), because each atom loses all of its valency electrons to form a positive ion (1).","P to Cl: the valency equals 8 minus the number of valency electrons (1), because each atom gains (or shares) electrons to complete its outer shell of eight (1)."]),
X4_D(15,"Ammonia as a reducing agent",3,"<p>Ammonia reacts with oxygen at high temperatures in the presence of a suitable catalyst to form nitric oxide, NO.</p><p style='text-align:center'>4NH<sub>3</sub>(g) + 5O<sub>2</sub>(g) → 4NO(g) + 6H<sub>2</sub>O(g)</p><ol type='a'><li>Explain how this chemical equation shows ammonia acting as a reducing agent. [1]</li><li>Suggest a suitable catalyst for the reaction from the list of metals. Give a reason for your answer.<br><b>aluminium &nbsp; calcium &nbsp; platinum &nbsp; potassium &nbsp; sodium</b><br>suitable catalyst ........<br>reason ........ [2]</li></ol>",["(a) Ammonia gains oxygen (nitrogen is oxidised from NH~3~ to NO), so ammonia is the reducing agent (1).","(b) Platinum (1); it is a transition metal that is unreactive (does not react with the reactants or products) (1)."]),
X4_D(16,"Sodium hydride",2,"<p>The symbol equation for the production of sodium hydride is shown.</p><p style='text-align:center'>2Na + H<sub>2</sub> → 2NaH</p><ol type='a'><li>Write a word equation for this reaction. [1]</li><li>Suggest why the hydrogen must be dry. [1]</li></ol>",["(a) sodium + hydrogen → sodium hydride (1).","(b) Sodium (and sodium hydride) reacts with water, so any moisture would react with the sodium instead (1)."]),
X4_D(17,"Potassium added to water",2,"<p>When potassium is added to water a chemical reaction occurs.</p><p>State <b>two</b> observations that can be made when potassium is added to water. [2]</p>",["Any two of: fizzes / bubbles (1); floats (1); melts into a ball (1); moves around on the surface (1); burns with a lilac flame (1); disappears (1)."]),
X4_D(18,"Chromium compared with Group I",4,"<p>Chromium is a transition element.</p><ul><li>Chromium has a high melting point.</li><li>Chromium is a good conductor of electricity.</li><li>Many chromium compounds are soluble in water.</li><li>Hydrated chromium(III) sulfate is green.</li><li>Chromium forms the chlorides CrC<i>l</i><sub>2</sub> and CrC<i>l</i><sub>3</sub>.</li><li>Oxides of chromium act as catalysts in the manufacture of poly(ethene).</li></ul><ol type='a'><li>Use this information to give <b>two</b> properties of chromium which are different from properties of Group I elements such as sodium.<br>1 ........<br>2 ........ [2]</li><li>Use this information to give <b>two</b> properties of chromium which are similar to properties of Group I elements such as sodium.<br>1 ........<br>2 ........ [2]</li></ol>",["(a) Any two of: high melting point (1); forms a green (coloured) compound (1); variable oxidation states / forms two chlorides CrCl~2~ and CrCl~3~ (1); oxides act as catalysts (1).","(b) Good conductor of electricity (1); many compounds are soluble in water (1)."]),
X4_D(19,"Group I metals and water",2,"<p>When Group I metals are added to water they fizz and an alkaline solution forms.</p><ol type='a'><li>Name the gas given off. [1]</li><li>Identify the ion present in the solution which makes the solution alkaline. [1]</li></ol>",["(a) Hydrogen (1).","(b) Hydroxide ion, OH^−^ (1)."]),
X4_D(20,"Group I metals vs transition metals: physical properties",2,"<p>Describe <b>two</b> ways in which the physical properties of Group I metals are different from those of transition metals.<br>1 ........<br>2 ........ [2]</p>",["Any two of: Group I metals have lower melting points (1); lower densities (1); are softer (1)."]),
X4_D(21,"Group I and transition metals: similar properties",2,"<p>Group I metals are very reactive. Transition elements are also metals but are less reactive than Group I metals.</p><p>State <b>two</b> physical properties of Group I metals which are similar to those of transition metals.<br>1 ........<br>2 ........ [2]</p>",["Any two of: good conductors of electricity (1); good conductors of heat (1); shiny when freshly cut (1); malleable (1); ductile (1)."]),
X4_D(22,"Element Z in Period 3, Group V",3,"<p>Element <b>Z</b> is in Period 3 and Group V.</p><ol type='a'><li>Identify element <b>Z</b>. [1]</li><li>Explain in terms of electron transfer why <b>Z</b> behaves chemically as a non-metal. [2]</li></ol>",["(a) Phosphorus (1).","(b) Its atoms gain electrons (1) to form negative ions (and complete the outer shell); metals lose electrons to form positive ions (1)."]),
X4_D(23,"Chlorine and sodium bromide",2,"<p>Chlorine reacts with aqueous sodium bromide.</p><p>The equation for the reaction is shown.</p><p style='text-align:center'>C<i>l</i><sub>2</sub> + 2NaBr → 2NaC<i>l</i> + Br<sub>2</sub></p><ol type='a'><li>State the type of reaction shown. [1]</li><li>Why is there <b>no</b> reaction between iodine and aqueous sodium bromide? [1]</li></ol>",["(a) Displacement (a redox reaction) (1).","(b) Iodine is less reactive than bromine, so it cannot displace bromine (1)."]),
X4_D(24,"Group I data table: sodium and rubidium",5,"<p>The table shows some properties of four metals in Group I of the Periodic Table.</p>"+X4_Q24+"<ol type='a'><li>Complete the table to estimate:<br>• the melting point of rubidium<br>• the relative electrical conductivity of sodium. [2]</li><li>What is the physical state of caesium at 20 °C? Give a reason for your answer. [2]</li><li>Describe the trend in the boiling points of the Group I metals. [1]</li></ol>",["(a) Melting point of rubidium: between 29 and 63 °C, about 39 °C (1); conductivity of sodium: a value greater than 14, about 20 (1).","(b) Solid (1); 20 °C is below the melting point of caesium (29 °C) (1).","(c) The boiling point decreases down the group (1)."]),
X4_D(25,"Chlorine and potassium iodide",3,"<p>Iodine is formed when chlorine reacts with aqueous potassium iodide.</p><ol type='a'><li>Complete the chemical equation for this reaction.<br><span style='display:block;text-align:center'>........ + 2KI → I<sub>2</sub> + ........KC<i>l</i></span> [2]</li><li>When aqueous iodine is mixed with aqueous potassium chloride, there is no reaction.<br>Suggest, in terms of chemical reactivity, why there is no reaction. [1]</li></ol>",["(a) Cl~2~ + 2KI → I~2~ + 2KCl: Cl~2~ (1); coefficient 2 (1).","(b) Iodine is less reactive than chlorine, so it cannot displace chlorine from potassium chloride (1)."]),
X4_D(26,"Group I data table: lithium and potassium",6,"<p>This question is about Group I elements.</p><p>The properties of some Group I elements are shown in the table.</p>"+X4_Q26+"<ol type='a'><li>Complete the table to estimate:<br>• the melting point of lithium [2]<br>• the atomic radius of potassium. [2]</li><li>Describe the trend in the boiling points of the Group I elements down the group. [1]</li><li>Caesium is below rubidium in Group I.<br>Use the information in the table to suggest why it is difficult to predict the thermal conductivity of caesium. [1]</li><li>Predict the physical state of rubidium at 45 °C. Give a reason for your answer. [2]</li></ol>",["(a) Melting point of lithium: a value above 97 °C, e.g. 100 to 200 °C (2); atomic radius of potassium: between 186 and 248 pm, about 227 pm (2). Award 1 mark if the value is only just outside the range but the right trend is shown.","(b) The boiling point decreases down the group (1).","(c) There is no regular trend in thermal conductivity (the values do not change by a steady amount) (1).","(d) Liquid (1); 45 °C is above the melting point (39 °C) but below the boiling point (686 °C) (1)."]),
X4_D(27,"Metals in the first 36 elements",2,"<p>The Periodic Table is very useful to chemists.</p><p>Refer only to elements with atomic numbers 1 to 36 in the Periodic Table provided when answering this question.</p><p>State which metal in the first 36 elements:</p><ol type='a'><li>is the Group I element which reacts most vigorously with water [1]</li><li>reacts with air to form lime. [1]</li></ol>",["(a) Potassium (1): francium and caesium are beyond element 36, rubidium is 37.","(b) Calcium (1): lime is calcium oxide."]),
X4_D(28,"Bromine and hydrogen sulfide",3,"<p>Bromine reacts with hydrogen sulfide, H<sub>2</sub>S.</p><ol type='a'><li>Complete the chemical equation for this reaction.<br><span style='display:block;text-align:center'>........ + H<sub>2</sub>S → ........HBr + S</span> [2]</li><li>The energy level diagram for this reaction is shown.</li></ol>"+X4_ENG()+"<p>Explain how this diagram shows that the reaction is exothermic. [1]</p>",["(a) Br~2~ + H~2~S → 2HBr + S: Br~2~ (1); coefficient 2 (1).","(b) The products are at a lower energy than the reactants, so energy is given out to the surroundings (1)."]),
X4_D(29,"Iodine and compounds of iodine",3,"<p>This question is about iodine and compounds of iodine.</p><ol type='a'><li>Complete the word equation to show the halogen and halide compound which react to form the products iodine and potassium bromide.<br><span style='display:block;text-align:center'>........ + ........ → iodine + potassium bromide</span> [2]</li><li>Explain, in terms of the reactivity of the halogens, why aqueous iodine does <b>not</b> react with aqueous potassium chloride. [1]</li></ol>",["(a) bromine (1) + potassium iodide (1) → iodine + potassium bromide.","(b) Iodine is less reactive than chlorine, so it cannot displace chlorine from potassium chloride (1)."]),
X4_D(30,"Group VII data table",3,"<p>The table shows the properties of some Group VII elements.</p>"+X4_Q30+"<ol type='a'><li>Use this information to:<br>• identify the physical state of fluorine at room temperature<br>• estimate the boiling point of chlorine. [2]</li><li>Suggest why the density of chlorine is much lower than the densities of bromine and iodine. [1]</li></ol>",["(a) Fluorine is a gas (1); boiling point of chlorine: between –188 and 59 °C, e.g. about –35 °C (accept values from –100 to 0 °C) (1).","(b) Chlorine is a gas, so its molecules are far apart, but bromine (liquid) and iodine (solid) have molecules close together (1)."]),
X4_D(31,"Potassium: flame, floating and hydrogen",3,"<p>The table shows the properties of some Group I elements.</p>"+X4_Q31+"<p>When potassium reacts with water, it floats and melts into a ball. A flame is observed.</p><ol type='a'><li>What colour does potassium give to the flame? [1]</li><li>Use the information in the table to suggest why potassium floats on water. [1]</li><li>Hydrogen is produced when potassium reacts with water.<br>Complete the dot-and-cross diagram to show the electron arrangement in a molecule of hydrogen. [1]"+FBLANK("H2","Outline of the hydrogen molecule")+"</li></ol>",["(a) Lilac (1).","(b) Potassium has a density of 0.86 g / cm^3^, which is less than that of water (1.0 g / cm^3^) (1).","(c) One shared pair of electrons (one dot and one cross) in the overlap of the two circles (1)."]),
X4_D(32,"Particles A to D",7,"<p>The table gives some information about four different particles, <b>A</b>, <b>B</b>, <b>C</b> and <b>D</b>.</p>"+X4_Q32+"<ol type='a'><li>Complete the table. The first row has been done for you. [4]</li><li>Give <b>two</b> particles from the table which are isotopes of each other. [1]</li><li>Element <b>Z</b> is in the same group of the Periodic Table as <b>A</b> and is less reactive than <b>A</b>.<br>State the identity of element <b>Z</b>. [1]</li><li><b>C</b> is unreactive.<br>Use information from the table to explain why. [1]</li></ol>",["(a) B has 11 electrons (1); C has 18 protons (1); D has electronic structure 2,8,8 (1); D has a charge of 1– (1).","(b) A and B (1): same number of protons but different numbers of neutrons.","(c) Lithium (1).","(d) C has a full outer shell of electrons (2,8,8) (1)."]),
X4_D(33,"Group I properties and reactions with water",4,"<p>This question is about Group I elements and their compounds.</p><p>The properties of some Group I elements are shown in the table.</p>"+X4_Q33+"<ol type='a'><li>Complete the table to estimate:<br>• the relative thermal conductivity of potassium<br>• the atomic radius of rubidium. [2]</li><li>Describe the trend in the boiling points of the Group I elements. [1]</li><li>Use the information in the table to predict what you would observe when rubidium reacts with cold water. [1]</li></ol>",["(a) Thermal conductivity of potassium: between 1.6 and 3.9, about 2.5 (1); atomic radius of rubidium: between 227 and 265 pm, about 248 (1).","(b) The boiling point decreases down the group (1).","(c) It bursts into flame (or explodes) after very rapid bubbling (1)."]),
X4_D(34,"Group VII data table: iodine and astatine",3,"<p>The properties of some Group VII elements are shown in the table.</p><p>Complete the table to suggest:</p><ul><li>the density of iodine</li><li>the melting point of astatine</li><li>the colour of astatine.</li></ul>"+X4_Q34+"<p>[3]</p>",["Density of iodine: between 3.1 and 6.4 g / cm^3^, about 4.9 (1).","Melting point of astatine: a value above 114 °C, up to about 337 °C, e.g. 300 °C (1).","Colour of astatine: black / dark grey-black (1)."]),
X4_D(35,"Manganese compared with sodium",3,"<p>Manganese is a transition element. Sodium is an element in Group I of the Periodic Table.</p><p>Describe <b>three</b> ways in which the properties of manganese differ from those of sodium.<br>1 ........<br>2 ........<br>3 ........ [3]</p>",["Any three of: higher melting point (1); higher density (1); harder (1); forms coloured compounds (1); variable oxidation states (1); acts as a catalyst (1); less reactive with water (1)."]),
X4_D(36,"Chlorine and zinc iodide",2,"<p>When chlorine is bubbled through a colourless aqueous solution of zinc iodide, the solution turns brown.</p><p>Name the brown substance.</p><p>Suggest, using ideas about the reactivity of the halogens, why this reaction occurs. [2]</p>",["The brown substance is iodine (1).","Chlorine is more reactive than iodine, so it displaces iodine from zinc iodide (1)."]),
X4_D(37,"Iron compared with potassium",3,"<p>Iron is a transition element. Potassium is an element in Group I of the Periodic Table.</p><p>Describe <b>three</b> ways in which the properties of iron differ from those of potassium.<br>1 ........<br>2 ........<br>3 ........ [3]</p>",["Any three of: higher melting point (1); higher density (1); harder (1); forms coloured compounds (1); variable oxidation states (1); acts as a catalyst (1); less reactive with water (1)."]),
X4_D(38,"Iron similar to Group I",2,"<p>Iron is a transition element.</p><p>A list of properties of iron is shown.</p><ul><li>Iron is a good conductor of electricity.</li><li>Iron forms soluble salts.</li><li>Iron forms coloured compounds.</li><li>Iron has variable oxidation states.</li><li>Iron has a catalyst.</li><li>Iron forms a basic oxide.</li></ul><p>Give <b>two</b> properties from the list in which iron is similar to Group I elements.<br>1 ........<br>2 ........ [2]</p>",["Any two of: iron is a good conductor of electricity (1); iron forms soluble salts (1); iron forms a basic oxide (1)."])
);
